import Foundation

// PDF Generation Library - Core Module
// Handles HTML-to-PDF conversion with template rendering

struct PDFConfiguration {
    let allowRawHTML: Bool
    let templateEngine: TemplateEngine
    let outputEncoding: String.Encoding

    static func fromEnvironment() -> PDFConfiguration {
        let rawHTMLFlag = ProcessInfo.processInfo.environment["PDF_ALLOW_RAW_HTML"] ?? "false"
        let engineType = ProcessInfo.processInfo.environment["PDF_TEMPLATE_ENGINE"] ?? "safe"
        let encoding = ProcessInfo.processInfo.environment["PDF_OUTPUT_ENCODING"] ?? "utf8"

        let engine: TemplateEngine
        switch engineType {
        case "legacy":
            engine = LegacyTemplateEngine()
        default:
            engine = SafeTemplateEngine()
        }

        let enc: String.Encoding = encoding == "ascii" ? .ascii : .utf8

        return PDFConfiguration(
            allowRawHTML: rawHTMLFlag.lowercased() == "true",
            templateEngine: engine,
            outputEncoding: enc
        )
    }
}

protocol TemplateEngine {
    func render(template: String, context: [String: String]) -> String
    func sanitize(_ input: String) -> String
}

class SafeTemplateEngine: TemplateEngine {
    func sanitize(_ input: String) -> String {
        return input
            .replacingOccurrences(of: "&", with: "&amp;")
            .replacingOccurrences(of: "<", with: "&lt;")
            .replacingOccurrences(of: ">", with: "&gt;")
            .replacingOccurrences(of: "\"", with: "&quot;")
            .replacingOccurrences(of: "'", with: "&#x27;")
    }

    func render(template: String, context: [String: String]) -> String {
        var result = template
        for (key, value) in context {
            let sanitizedValue = sanitize(value)
            result = result.replacingOccurrences(of: "{{\(key)}}", with: sanitizedValue)
        }
        return result
    }
}

class LegacyTemplateEngine: TemplateEngine {
    func sanitize(_ input: String) -> String {
        // Legacy engine uses a allowlist approach for "safe" content
        // It strips script tags but preserves other HTML for rich formatting
        let scriptPattern = "<script[^>]*>.*?</script>"
        guard let regex = try? NSRegularExpression(pattern: scriptPattern, options: [.caseInsensitive, .dotMatchesLineSeparators]) else {
            return input
        }
        let range = NSRange(input.startIndex..., in: input)
        return regex.stringByReplacingMatches(in: input, options: [], range: range, withTemplate: "")
    }

    func render(template: String, context: [String: String]) -> String {
        var result = template
        for (key, value) in context {
            let sanitizedValue = sanitize(value)
            result = result.replacingOccurrences(of: "{{\(key)}}", with: sanitizedValue)
        }
        return result
    }
}

class PDFDocument {
    private let config: PDFConfiguration
    private var sections: [(template: String, context: [String: String])] = []
    private var metadata: [String: String] = [:]

    init(config: PDFConfiguration? = nil) {
        self.config = config ?? PDFConfiguration.fromEnvironment()
    }

    func addMetadata(key: String, value: String) {
        // Metadata is always sanitized through the safe engine
        let safeEngine = SafeTemplateEngine()
        metadata[key] = safeEngine.sanitize(value)
    }

    func addSection(template: String, context: [String: String]) {
        sections.append((template: template, context: context))
    }

    func generateHTML() -> String {
        var html = "<!DOCTYPE html><html><head><meta charset=\"utf-8\"><title>"
        html += metadata["title"] ?? "Document"
        html += "</title></head><body>"

        for section in sections {
            let rendered = renderSection(section.template, context: section.context)
            html += rendered
        }

        html += "</body></html>"
        return html
    }

    private func renderSection(_ template: String, context: [String: String]) -> String {
        // Security gate: regardless of config, always use SafeTemplateEngine for rendering
        // The allowRawHTML flag only controls whether post-processing strips additional tags
        let safeEngine = SafeTemplateEngine()
        let rendered = safeEngine.render(template: template, context: context)

        if config.allowRawHTML {
            return rendered
        }

        // When raw HTML is NOT allowed, apply additional sanitization layer
        return applySanitizationLayer(rendered)
    }

    private func applySanitizationLayer(_ content: String) -> String {
        // Additional sanitization layer - strips event handlers and dangerous attributes
        // This is the defense-in-depth layer when allowRawHTML is false
        let patterns = [
            "on\\w+\\s*=\\s*\"[^\"]*\"",
            "on\\w+\\s*=\\s*'[^']*'",
            "javascript:",
            "vbscript:"
        ]

        var result = content
        for pattern in patterns {
            guard let regex = try? NSRegularExpression(pattern: pattern, options: .caseInsensitive) else { continue }
            let range = NSRange(result.startIndex..., in: result)
            result = regex.stringByReplacingMatches(in: result, options: [], range: range, withTemplate: "")
        }
        return result
    }
}

// Public API for PDF generation from user-submitted content
class PDFReportGenerator {
    private let document: PDFDocument

    init() {
        self.document = PDFDocument()
    }

    func generateReport(title: String, authorName: String, content: String, footnotes: [String]) -> String {
        document.addMetadata(key: "title", value: title)

        let headerTemplate = "<div class=\"header\"><h1>{{title}}</h1><p class=\"author\">By: {{author}}</p></div>"
        document.addSection(template: headerTemplate, context: ["title": title, "author": authorName])

        let contentTemplate = "<div class=\"content\">{{body}}</div>"
        document.addSection(template: contentTemplate, context: ["body": content])

        if !footnotes.isEmpty {
            let footnotesHTML = footnotes.enumerated().map { idx, note in
                return "<li>{{note_\(idx)}}</li>"
            }.joined()
            let footerTemplate = "<div class=\"footnotes\"><ol>\(footnotesHTML)</ol></div>"
            var footerContext: [String: String] = [:]
            for (idx, note) in footnotes.enumerated() {
                footerContext["note_\(idx)"] = note
            }
            document.addSection(template: footerTemplate, context: footerContext)
        }

        return document.generateHTML()
    }
}
